    out_col = mix(out_col, vec3f(0.020, 0.024, 0.018), smoothstep(0.60 - q * 0.05, 0.94, coarse) * (0.14 + q * 0.12));
    out_col = mix(out_col, vec3f(0.72, 0.70, 0.58), fleck * (0.10 + q * 0.08));
