    let threshold_bloom = smoothstep(0.55 - q * 0.04, 0.92, luma);
    out_col = out_col + out_col * threshold_bloom * (0.10 + q * 0.05);
    out_col = mix(out_col, vec3f(0.015, 0.018, 0.020), fleck * (0.06 + q * 0.04));
